#!/usr/bin/env python3
"""
CortexOS Self-Extracting Repository Bundle (Steps 1-6).
Run `python3 unpack_cortexos.py` to generate `cortexos-full-stack-v1.zip`
and extract the complete `./cortexos/` directory tree locally.
"""
import base64
import io
import zipfile

ZIP_B64 = ""

def main():
    raw_bytes = base64.b64decode(ZIP_B64)
    zip_path = "cortexos-full-stack-v1.zip"
    with open(zip_path, "wb") as f:
        f.write(raw_bytes)
    print(f"[+] Wrote {zip_path} ({len(raw_bytes)} bytes)")

    with zipfile.ZipFile(io.BytesIO(raw_bytes), "r") as zf:
        zf.extractall(".")
        print(f"[+] Extracted {len(zf.namelist())} files into ./cortexos/")

if __name__ == "__main__":
    main()
